const browserPluginRoot = process.env.ZCODE_PLUGIN_ROOT ?? process.env.CLAUDE_PLUGIN_ROOT;
if (!browserPluginRoot) throw new Error('Browser plugin root is unavailable in the node_repl host');
const { join } = await import('node:path');
const { pathToFileURL } = await import('node:url');
const { setupBrowserRuntime } = await import(pathToFileURL(join(browserPluginRoot, 'scripts', 'browser-client.mjs')).href);
await setupBrowserRuntime({ globals: globalThis });
const browser = await agent.browsers.get('iab');
const tabId = '{{latestBrowserTabId}}';
const tabs = await browser.tabs.list();
const tab = await browser.tabs.get(tabId);
const stateBefore = await tab.playwright.getByRole('status').innerText();
await tab.playwright.getByLabel('State').fill('after-restart');
const verifyOk = tabs.length === 1 && tabs[0]?.id === tabId && stateBefore === 'before-restart';
({ marker: verifyOk ? 'E2E_NODE_REPL_FRONTEND_RESTART_VERIFY_OK' : 'E2E_NODE_REPL_FRONTEND_RESTART_VERIFY_FAILED', tabId, count: tabs.length, stateBefore });
